     1→/**
     2→ * Error Utilities - Format API errors for user display
     3→ */
     4→
     5→/**
     6→ * Pydantic validation error structure from FastAPI
     7→ */
     8→interface ValidationError {
     9→  type: string;
    10→  loc: (string | number)[];
    11→  msg: string;
    12→  input?: any;
    13→}
    14→
    15→/**
    16→ * Translation map for common error messages to Spanish
    17→ */
    18→const ERROR_TRANSLATIONS: Record<string, string> = {
    19→  'Field required': 'Campo requerido',
    20→  'field required': 'Campo requerido',
    21→  'Invalid value': 'Valor inválido',
    22→  'invalid value': 'Valor inválido',
    23→  'Client not found': 'Cliente no encontrado',
    24→  'client not found': 'Cliente no encontrado',
    25→  'Invalid contract type': 'Tipo de contrato inválido',
    26→  'invalid contract type': 'Tipo de contrato inválido',
    27→  'value is not a valid enumeration member': 'Tipo de contrato inválido',
    28→  'NIT must be at least 5 characters': 'El NIT debe tener al menos 5 caracteres',
    29→};
    30→
    31→/**
    32→ * Format field name from validation error location
    33→ */
    34→function formatFieldName(loc: (string | number)[]): string {
    35→  const fieldMap: Record<string, string> = {
    36→    'client_nit': 'NIT del cliente',
    37→    'contract_type': 'Tipo de contrato',
    38→    'rut_file': 'Archivo RUT',
    39→  };
    40→
    41→  // Get the last item in the location array (usually the field name)
    42→  const field = loc[loc.length - 1];
    43→  return fieldMap[String(field)] || String(field);
    44→}
    45→
    46→/**
    47→ * Format a single Pydantic validation error
    48→ */
    49→function formatValidationError(error: ValidationError): string {
    50→  const fieldName = formatFieldName(error.loc);
    51→
    52→  // Try to find a translation for the error message
    53→  const translatedMsg = ERROR_TRANSLATIONS[error.msg] || error.msg;
    54→
    55→  return `${fieldName}: ${translatedMsg}`;
    56→}
    57→
    58→/**
    59→ * Format API error for user display
    60→ *
    61→ * Handles various error formats from the backend:
    62→ * - Pydantic validation errors (array of ValidationError objects)
    63→ * - Simple string error messages
    64→ * - Error objects with detail property
    65→ * - Unknown error formats
    66→ *
    67→ * @param error - The error object from axios or other source
    68→ * @returns User-friendly error message in Spanish
    69→ */
    70→export function formatApiError(error: any): string {
    71→  // Default fallback message
    72→  const defaultMessage = 'Error al procesar la solicitud. Por favor intente nuevamente.';
    73→
    74→  try {
    75→    // Handle axios error structure
    76→    if (error?.response?.data) {
    77→      const { detail } = error.response.data;
    78→
    79→      // Case 1: Pydantic validation errors (array of error objects)
    80→      if (Array.isArray(detail)) {
    81→        const validationErrors = detail as ValidationError[];
    82→        if (validationErrors.length > 0) {
    83→          // Format all validation errors
    84→          const messages = validationErrors.map(formatValidationError);
    85→          return messages.join('; ');
    86→        }
    87→      }
    88→
    89→      // Case 2: Simple string error message
    90→      if (typeof detail === 'string') {
    91→        // Check if we have a translation
    92→        return ERROR_TRANSLATIONS[detail] || detail;
    93→      }
