 */
import React, { useState } from 'react';
import {
  Box,
  TextField,
  Button,
  Card,
  CardContent,
  Typography,
  Grid,
  Alert,
  CircularProgress,
  Divider,
} from '@mui/material';
import {
  Search as SearchIcon,
  Warehouse as WarehouseIcon,
  CheckCircle as CheckCircleIcon,
  UploadFile as UploadFileIcon,
} from '@mui/icons-material';
import { legalService } from '../../services/legalService';
import { operationsService } from '../../services/operationsService';
import type { Client, ContractGeneration } from '../../types/legal';

const FKInventarioRequest: React.FC = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [searching, setSearching] = useState(false);
  const [requesting, setRequesting] = useState(false);
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [searchResults, setSearchResults] = useState<Client[]>([]);
  const [requestedContract, setRequestedContract] = useState<ContractGeneration | null>(null);
  const [error, setError] = useState<string | null>(null);

  // RUT file upload state
  const [rutFile, setRutFile] = useState<File | null>(null);
  const [rutFileName, setRutFileName] = useState<string>('');
  const [fileError, setFileError] = useState<string | null>(null);

  const handleSearch = async () => {
    setSearching(true);
    setError(null);
    setSearchResults([]);
    setSelectedClient(null);

    try {
      const results = await legalService.searchClients({ query: searchQuery.trim() || undefined });
      setSearchResults(results);

      if (results.length === 0) {
        setError('No se encontraron clientes con ese criterio de búsqueda');
      } else if (results.length === 1) {
        // Auto-select if only one result
        setSelectedClient(results[0]);
      }
    } catch (err) {
      setError('Error al buscar clientes. Por favor intente nuevamente.');
      console.error('Search error:', err);
    } finally {
      setSearching(false);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    // Validate PDF
    if (file.type !== 'application/pdf') {
      setFileError('Solo se permiten archivos PDF');
      setRutFile(null);
      setRutFileName('');
      return;
    }

    // Validate size (5MB)
    if (file.size > 5 * 1024 * 1024) {
      setFileError('El archivo no debe superar 5MB');
      setRutFile(null);
      setRutFileName('');
      return;
    }

    setRutFile(file);
    setRutFileName(file.name);
    setFileError(null);
  };

  const handleRequestContract = async () => {
    if (!selectedClient) {
      setError('Por favor seleccione un cliente');
      return;
    }

    if (!rutFile) {
      setError('Debe cargar el documento RUT del operador custodio');
      return;
    }

    setRequesting(true);
    setError(null);
    setFileError(null);

    try {
      const contract = await operationsService.requestInventarioBodegaGeneration(selectedClient.nit, rutFile);

      setRequestedContract(contract);
      setSearchQuery('');
      setSelectedClient(null);
      setSearchResults([]);
      setRutFile(null);
      setRutFileName('');
    } catch (err: any) {
      const errorDetail = err.response?.data?.detail || 'Error al solicitar el Inventario Bodega de 3ro';
      setError(errorDetail);
      console.error('Request error:', err);
    } finally {
      setRequesting(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('es-CO', {
      style: 'currency',
      currency: 'COP',
      minimumFractionDigits: 0,
    }).format(amount);
  };

  return (
    <Box>
      {/* Success Message */}
      {requestedContract && (
        <Alert
          severity="success"
          icon={<CheckCircleIcon />}
          sx={{ mb: 3 }}
          onClose={() => setRequestedContract(null)}
        >
          <Typography variant="body1" sx={{ fontWeight: 600 }}>
            ¡Solicitud de Inventario Bodega de 3ro enviada exitosamente!
          </Typography>
          <Typography variant="body2">
            ID: {requestedContract.contract_id} - El contrato está pendiente de revisión legal.
          </Typography>
        </Alert>
      )}

      {/* Error Message */}
      {error && (
        <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {/* Search Section */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ fontWeight: 600 }}>
