                        <Box sx={{ display: 'flex', gap: 1 }}>
                          <Button
                            variant="outlined"
                            startIcon={downloading === contract.id ? <CircularProgress size={16} /> : <DocIcon />}
                            size="small"
                            onClick={() => handleDownload(contract.id, 'docx')}
                            disabled={downloading === contract.id}
